// Formata a lista de execucoes num formato simples e seguro pro wrapper
// do cliente consumir -- so data e status, nada de dados internos do n8n.
const STATUS_LABELS = {
  success: 'Enviado',
  error: 'Falhou',
  running: 'Gerando...',
  waiting: 'Na fila',
};

let executions = [];
try {
  executions = $input.first().json.data || [];
} catch (e) {
  executions = [];
}

const items = executions.map(e => {
  const date = new Date(e.startedAt);
  return {
    date: date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' }),
    time: date.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
    status: STATUS_LABELS[e.status] || e.status,
    ok: e.status === 'success',
  };
});

return [{ json: { items } }];
